from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/system_design/design_lab.json").read_text(encoding="utf-8")
)
import math

model = lab["spam"]["model"]
x = lab["spam"]["validation"][0]["features"]
logit = model["intercept"] + sum(
    (
        w * (v - mu) / s
        for v, mu, s, w in zip(x, model["mean"], model["scale"], model["weights"])
    )
)
result = (
    1 / (1 + math.exp(-logit))
    if logit >= 0
    else math.exp(logit) / (1 + math.exp(logit))
)
print(result)
